int main() {
    int deliveryDays = 2;

    if (deliveryDays <= 1) {
        cout << "Same-day delivery!" << endl;
    }
    else if (deliveryDays <= 3) {
        cout << "Priority delivery!" << endl;
    }
    else if (deliveryDays <= 7) {
        cout << "Standard delivery." << endl;
    }
    else {
